import{_ as t,o as s,c as o,a3 as e}from"./chunks/framework.Dz5Q8p4s.js";const c=JSON.parse('{"title":"MechVerse: Evaluating Physical Motion Consistency in Video Generation Models","description":"","frontmatter":{"title":"MechVerse: Evaluating Physical Motion Consistency in Video Generation Models","arxiv":"2605.14843","date":"2026-05-14","authors":"Rahul Jain, Mayank Patel, Asim Unmesh, Karthik Ramani","categories":"cs.CV","topics":"物理感知视频生成, 机构运动学, 评测基准","outline":[2,2]},"headers":[],"relativePath":"papers/2605.14843.md","filePath":"papers/2605.14843.md","lastUpdated":null}'),n={name:"papers/2605.14843.md"};function r(i,a,l,d,p,h){return s(),o("div",null,[...a[0]||(a[0]=[e('<h1 id="mechverse-evaluating-physical-motion-consistency-in-video-generation-models" tabindex="-1">MechVerse: Evaluating Physical Motion Consistency in Video Generation Models <a class="header-anchor" href="#mechverse-evaluating-physical-motion-consistency-in-video-generation-models" aria-label="Permalink to &quot;MechVerse: Evaluating Physical Motion Consistency in Video Generation Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2605.14843" target="_blank" rel="noreferrer">2605.14843</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-05-14</td></tr><tr><td><strong>作者</strong></td><td>Rahul Jain, Mayank Patel, Asim Unmesh, Karthik Ramani</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用 Unity 渲染 1,357 个机械装配体的 21,156 段视频、按独立/成对耦合/密集耦合分三档难度，配六段式结构化提示，逼出 I2V 模型&quot;画面顺滑但机构错了&quot;的系统性盲区。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>现有视频生成评测几乎都在自然场景、人体动作和泛化物体运动上做文章，度量的是感知质量、时序连贯与文本对齐。机械装配体把另一类约束摆到台面上：零件之间的运动由刚体几何、接触耦合和运动链传动决定，齿轮必须协同旋转、凸轮-从动件必须把旋转转成平动、连杆必须把运动传到下游零件。这类约束是<strong>确定性的且全局传播的</strong>——错一处，整台机器就错了，但视频看上去仍然可以很顺。作者要问的问题因此非常具体：当前 image-to-video 模型能不能保持零件级的几何与运动学约束？</p><p>这件事的重要性有三层。工程上，I2V 正在被用于装配教学、CAD 与数字孪生可视化，一段&quot;零件动错了&quot;的视频对这些场景等于零价值。科学上，&quot;视频模型隐式学到了世界动力学&quot;这个大命题需要更硬的探针，而现有物理评测（VideoPhy、PhysGenBench、Physics-IQ）集中在刚体碰撞、流体这类连续现象，很少碰约束确定、耦合全局的铰接机构。方法论上，把依赖复杂度从&quot;零件独立&quot;连续调到&quot;密集耦合&quot;，就得到了一条受控的组合泛化坐标轴——CLEVR 与 Physion 当年正是靠这种诊断式设计推动进展的。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>通用视频评测</strong>（VBench、EvalCrafter、FETV）覆盖场景与动作很广，但不显式研究机械装配体，也无法控制运动是独立的、成对耦合的还是多零件传播的。<strong>物理一致性评测</strong>（VideoPhy、Towards World Simulator）与训练侧方案（WISA 的物理标注、PhyT2V 的提示自精化）针对的是全局物理真实感，不是零件间的结构化运动学耦合。<strong>铰接物体数据集</strong>这一支资源丰富——PartNet-Mobility 给出 2000+ 物体的关节标注，Shape2Motion、RPM-Net、ACD、GAPartNet 扩展到关节发现与功能部件语义，Patel 等人还专门做了 693 个 CAD 齿轮装配体的点云耦合运动预测基准；视频侧则有 HA-ViD 与 IKEA Video Manuals 的装配录像。作者的批评落点很准：这些资源全都服务于 3D 运动估计或动作识别，<strong>没有一个提供&quot;结构化提示 + 受控运动学复杂度&quot;配对的生成式视频评测数据</strong>。换句话说，缺口不是&quot;没人研究铰接物体&quot;，而是&quot;铰接物体的知识从未被组织成能评测 I2V 条件生成的形式&quot;。</p><p>现有提示格式本身也是障碍。像&quot;一个盒子在打开&quot;这样的语义级描述留了太多自由度，模型可以幻想出看着合理但违反机构的运动，评测者也无从判定它错在哪。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>先看已有的失败观察：I2V 模型在 VBench 上运动平滑度普遍 &gt;98、时序闪烁接近 99，可人眼一看装配动画就觉得不对。这个落差本身提示&quot;感知指标与机构正确性是两条互不相关的轴&quot;。接着看手上已有的资源：PartNet-Mobility 有现成的关节参数（<code>mobility_v2.json</code>），CAD 软件自带运动学求解器，Unity 可以做帧精确的归一化时间步进渲染——也就是说，<strong>真值运动是可以被精确生成而不是标注的</strong>。第三步是提示设计：既然运动由零件身份、静止支撑、运动基元、方向、幅度和依赖关系共同决定，那就把这六项显式写进提示，条件本身就不再有歧义。</p><p>最后一步是作者真正踩过的坑：他们先试了用 MLLM 自动标注（附录 A.6 完整记录了这次失败）。在 Easy 档的箱子上，MLLM 能正确识别摆动的盖子与静止的机身；到了 Medium 档的凸轮-从动件，绿色凸轮的连续旋转被三种提示生成策略<strong>一致地</strong>误判成直线运动，错误直接传进提示文本。这个失败反过来说明了两件事：耦合运动确实是当前多模态模型的硬伤（这正是要测的东西），以及标注必须由机械工程背景的人来做。于是有了两名标注员 + 受控词表 + GPT-4o mini 仅做措辞润色（严格禁止增删内容）+ 二次复核的流水线。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>机械装配体是一类特殊的物理场景：它的正确运动是<strong>唯一确定</strong>的，而且约束会沿运动链全局传播。这让它成为理想探针——模型只要没真正理解机构，错误就一定会在下游零件上暴露出来，而不是像流体那样可以&quot;看着差不多就算对&quot;。同时，把零件涂成扁平哑光的纯色并在提示里逐色点名，就把&quot;哪个零件该动、该怎么动&quot;变成了一个可被外部检查的命题，而不是模糊的整体印象。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以测试集里的洗衣机（Easy 档）与 Oldham 联轴器（Hard 档）为例：</p><ul><li><strong>数据来源</strong>：21,156 段视频、1,357 个装配体、141 个类别。904 个来自 PartNet-Mobility（Easy 档，日常铰接物体），453 个是本文自建的 CAD 装配体（Medium/Hard 档，覆盖连杆、凸轮-从动件、齿轮系、发动机活塞等）。</li><li><strong>三档复杂度</strong>：Easy 15,720 段（1–2 个零件、运动独立，如门摆动、抽屉滑出）；Medium 2,412 段（3–8 个零件，一个旋转输入通过连杆或接触驱动其他部件，如四杆机构、凸轮-从动件、Hobson 联轴器）；Hard 3,024 段（10 个以上零件，密集耦合且 2D 投影下频繁自遮挡）。</li><li><strong>三轴变体</strong>：速度按关节行程覆盖比例定义——Slow 走一半、Mid 走满、Fast 走两遍（CAD 对应 180°/360°/720°）；视角上 PartNet 三机位、CAD 两机位；方向上把正向片段倒放得到语义相反的运动（开↔关、顺时针↔逆时针）。全部 32 帧、16 FPS、2 秒。正向 14,508 段、倒放 6,648 段。</li><li><strong>六段式提示</strong>：装配体概述 → 按扁平哑光颜色标识零件 → 逐色标注运动/刚性 → 运动类型（旋转/平动/旋转+平动/平面运动）→ 方向 → 速度描述。同一张输入图只改提示的方向与速度字段，就能得到四段语义不同的真值片段（关-慢半程、关-整周期、开-整周期、关-两周期）。</li><li><strong>划分</strong>：训练 18,672 / 测试 1,004，按<strong>类别级留出</strong>——测试集的 8 个类别（Bucket、CamAndFollower、FoldingChair、Microwave、Refrigerator、Safe、UniqueMechanism、WashingMachine）完全不出现在训练集，覆盖三档（476 Easy / 294 Medium / 234 Hard），且全部只用 Cam1 渲染，另有 1,480 段同装配体的其他视角被从两个划分中一并排除。</li><li><strong>评测</strong>：14 个 I2V 系统——闭源 Wan2.7、Kling3、Happy Horse；开源 CogVideoX-1.0/1.5、DynamiCrafter、HunyuanVideo-1.5、LTX-2、LTX-Video、VideoCrafter、Wan2.2、ConsistI2V；以及在训练集上 LoRA（rank 32、2 epoch）微调的 CogVideoX-1.0 与 Wan2.2。指标是 VBench-I2V 加 WorldModelBench（指令遵循 / 物理定律 / 常识，剔除流体子类），再加人评。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：感知指标能否反映机构正确性？</strong> 答案是明确的不能。几乎所有模型的运动平滑度都在 98 以上、时序闪烁接近 99，而 WorldModelBench 上闭源最强的 Kling3 总分只有 7.66，Wan2.7 7.59、Happy Horse 与 HunyuanVideo-1.5 并列 7.56。有意思的是开源模型在感知指标上并不吃亏——HunyuanVideo-1.5 拿下多项 VBench 最佳，VideoCrafter 成像质量最高——差距集中在指令遵循上。</p><p><strong>问题二：难度上升时模型表现如何？</strong> 这里出现了整篇论文最关键的观察：VBench 指标从 Easy 到 Hard 几乎不变（作者据此说它无法分辨三档），而 WorldModelBench 的总分竟然<strong>随复杂度上升</strong>——HunyuanVideo-1.5 从 7.26 涨到 7.67 再到 8.03，Happy Horse 从 7.14→7.80→8.12，Kling3 从 7.41→7.80→8.00，DynamiCrafter 从 6.34→6.86→7.12。人评则给出相反的方向：运动正确性与运动学耦合分数在 Medium 与 Hard 上下降。作者的解释是 MLLM 裁判在复杂装配体上倾向于给&quot;全局看着合理&quot;的视频高分，即便零件级约束被破坏。附录的定性分析佐证了这一点：Hard 档里排名靠前的模型生成了视觉上很讨喜的动画，但底层连杆根本没把运动传下去，模型更像是从视觉相似的真实内容里幻想出运动模式。</p><p><strong>问题三：速度与方向的影响？</strong> 速度是分辨力最弱的一轴，WorldModelBench 上多数模型跨 Slow/Mid/Fast 变化不到 0.2；VBench 上则是快片段一律更难。方向上倒放片段在 WorldModelBench 上略高（HunyuanVideo-1.5 正向 7.44/7.59 → 倒放 7.75），在 VBench 一致性指标上却一律更低。</p><p><strong>问题四：在 MechVerse 上微调有用吗？</strong> 结果分化：CogVideoX 的 WorldModelBench 总分从 5.79 升到 6.64，几乎全线改善；Wan2.2 却从 6.56 掉到 6.15——感知质量和动态度上去了，物理定律与常识分下来了。作者的结论是机构感知微调对弱基座帮助大，对强基座可能以物理推理为代价换取感知增益。</p><p><strong>人评细节</strong>：43 个装配体、6 位评估者、12 个维度、1–5 分李克特量表。HunyuanVideo-1.5 总均分 2.91 最高，Happy Horse 2.89、Wan2.7 2.78、微调后 Wan2.2 2.65——<strong>全部低于中位 3.0</strong>。Krippendorff <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span> 为运动正确性 0.72、视觉真实感 0.63、提示遵循 0.77。</p><p>需要指出的三处小瑕疵：图 1 与 §6.3 的行文里把基准称作 &quot;MechBench&quot;，与全文的 MechVerse 不一致；图 15 标题写&quot;全部 15 个模型&quot;而 §A.7 正文与表 1 都是 14 个；图 2 标题给出的相机分布（Cam1 25%、Cam2 38%、Cam3 37%）与表 2 的绝对数（7,958/7,958/5,240，即 37.6%/37.6%/24.8%）对不上，看起来是标签顺序错位。这些不影响主结论，但读表时需留意。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：MechVerse 用 Unity 从 PartNet-Mobility 和自建 CAD 装配体渲染出 21,156 段真值精确的机构动画，按独立/成对耦合/密集耦合分三档，每段配一条把零件、支撑、运动基元、方向、速度、依赖关系全写死的六段式提示。在 14 个 I2V 系统上，感知指标几乎不随耦合复杂度变化，MLLM 裁判的分数甚至随复杂度上升，而人评的运动正确性与运动学耦合分数下降。最高的人评总分只有 2.91（满分 5），且没有任何模型能正确生成凸轮-从动件的耦合运动。用 MechVerse 微调对弱基座（CogVideoX 5.79→6.64）有效，对强基座（Wan2.2 6.56→6.15）反而损害物理推理。主结论是：当前 I2V 的瓶颈是机构级运动推理，不是视觉保真度。</p><p><strong>3 句话版</strong>：机械装配体的运动唯一确定且沿运动链全局传播，是检验&quot;视频模型是否理解世界动力学&quot;的硬探针。MechVerse 提供了受控难度、真值精确、提示无歧义的 21K 段评测数据。结果显示视觉指标与 MLLM 裁判都测不出机构错误，只有人评能看见，且所有模型都远未及格。</p><p><strong>1 句话版</strong>：用真值可控的机械装配体动画证明，当前 I2V 模型能把画面画顺，却不能把机器算对。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最致命的一条是：<strong>论文的核心结论只由那个 43 装配体、6 位评估者的人评研究支撑</strong>。这不是&quot;limitation 之一&quot;，而是逻辑上的单点承重——作者自己已经论证了 VBench-I2V 分不出三档、WorldModelBench 的方向与人评相反，等于亲手排除了两套自动指标作为证据。于是&quot;错误随耦合复杂度上升&quot;这个中心 claim 完全依赖一次小规模主观评测，而报告中没有任何置信区间：前四名的总均分是 2.91 / 2.89 / 2.78 / 2.65，在 1–5 量表、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.72</span></span></span></span> 的条件下，这个排序很可能不显著。</p><p>更要命的是，MechVerse <strong>手里握着真值却没用</strong>。数据集不仅发布视频和提示，还发布了全部装配体的 OBJ 与关节参数；每个零件被赋予固定的扁平哑光纯色（同一关节下所有 OBJ 共享一种颜色），这意味着零件级跟踪几乎是免费的。既然真值关节轨迹存在、生成视频里的零件又可以按颜色分割，那么&quot;生成的第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 号零件转了多少度、是否与驱动件保持正确的传动比&quot;是可以直接算出来的。论文没有定义任何这样的指标，反而借用了两套自己刚证明不适用的外部指标。如果那次小规模人评的结论不稳（例如换一批评估者后 Easy/Medium/Hard 的差异消失），这篇工作的中心论断就没有任何定量支撑了。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>目标是补上论文缺的那个指标，一周可完成，不需要训练任何模型：</p><ul><li><strong>数据</strong>：只用测试集里的 294 段 Medium + 234 段 Hard 片段（都是 Cam1、32 帧），配套的真值视频与关节参数已随数据集发布。</li><li><strong>实现</strong>：利用扁平哑光配色做逐零件分割（颜色聚类即可，不需要 SAM），对每个零件在真值视频和生成视频中分别提取质心轨迹与主轴朝向，得到逐帧的平动位移与旋转角。定义两个量：<strong>零件轨迹误差</strong>（生成 vs 真值的角度/位移 RMSE，按行程归一化）与<strong>耦合相关度</strong>（驱动件角度序列与从动件位移序列的相关系数，和真值对应值之差）。</li><li><strong>测量</strong>：对 6 个模型（3 闭源 + 3 开源）计算这两个量，并按 Easy/Medium/Hard 分层。</li><li><strong>判据</strong>：若两个量从 Easy 到 Hard 单调恶化，且模型排序与人评的运动正确性维度大体一致（Spearman &gt; 0.6），则该指标可替代人评，论文的中心 claim 获得定量支撑；若指标在三档间无差异，或与人评排序不相关，则说明&quot;耦合复杂度导致失败&quot;这一结论需要重新审视——也可能说明扁平配色让零件跟踪太容易，掩盖了真实难度。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的攻击是构造一个**&quot;故意做错但指标看不出&quot;的 oracle**。数据集的结构让这件事异常容易：同一张输入图对应四段真值片段（慢-关、中-关、中-开、快-关）。于是把&quot;生成视频&quot;直接替换成<strong>真值视频，但取错误的速度/方向变体</strong>——它在 VBench-I2V 的每一项上都会接近满分（真实渲染、完美平滑、零闪烁、主体一致性完美），在 WorldModelBench 的物理与常识项上也应当很高（它确实是一段物理正确的机构动画），却在提示所要求的方向或速度上<strong>完全错误</strong>。</p><p>如果这个 oracle 的综合分数超过所有真实被评模型（大概率会），那就证明论文使用的两套自动指标不仅&quot;分辨力不足&quot;，而是<strong>对本文关心的属性完全无响应</strong>——它们无法把&quot;错误的机构行为&quot;与&quot;正确的机构行为&quot;区分开，只要画面来自真实渲染。这比论文现有的&quot;WorldModelBench 随复杂度上升&quot;更强：后者只说明指标有偏，前者说明指标与目标属性正交。</p><p>第二条攻击针对倒放数据本身。倒放片段是正向片段的帧序反转，对绝大多数可逆运动链而言在物理上同样合法，因此&quot;方向错误&quot;在这些样本上并不构成物理违规，只构成<strong>指令不遵循</strong>。这意味着 31% 的数据在物理评测维度上是退化的，而 WorldModelBench 的物理项恰恰会把倒放片段判为合理——这为&quot;倒放片段在 WorldModelBench 上得分更高&quot;提供了一个比论文所给更简单的解释。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：MechVerse 目前问的是&quot;生成的像素动得对不对&quot;，而机构的本质不是像素轨迹，而是<strong>零件之间的约束关系</strong>。用像素级或 MLLM 级指标去逼近一个离散的结构性对象，注定测不准——论文自己的实验就是证据。</p><p><strong>可借鉴的相邻领域工具</strong>：铰接物体的运动学辨识与系统辨识——从观测轨迹反推关节类型、旋转轴位置和传动比，这在机器人学（关节参数估计）与机械工程（机构综合）里都是成熟问题；Patel 等人的 DYNAMO 已经在点云上做过依赖感知的耦合运动预测。</p><p><strong>新 framing</strong>：把评测从&quot;比较视频&quot;改成&quot;比较机器&quot;。给定一段生成视频，先从零件颜色轨迹<strong>拟合出一张运动学图</strong>——节点是零件，边是关节类型（旋转/平动）与传动关系（相位差、传动比、是否同步），然后把这张图与真值机构的图做结构比对。评分不再是&quot;轨迹误差多少像素&quot;，而是&quot;模型的视频蕴含的是不是同一台机器&quot;。这个 framing 的好处是天然分级：拓扑错（该动的没动）、类型错（该转的在平动）、参数错（传动比不对）是三种可分离的失败，正好对应人评里那些说不清的维度。</p><p><strong>第一个实验长什么样</strong>：先在 Medium 档最规整的凸轮-从动件与四杆机构上验证可行性。对每段视频提取驱动件的角度序列 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span></span></span></span> 与从动件的位移序列 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">s</span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span></span></span></span>，估计传递函数并比较其谐波成分——凸轮-从动件的真值传递函数有明确的谐波签名，一个&quot;把凸轮转起来但从动件不动&quot;的失败会在基频幅值上直接归零。先在真值视频上验证辨识器的可靠性（真值应当恢复出正确的传动关系），再跑到 14 个模型的生成视频上，检查得到的失败分类是否与人评的 12 个维度对得上。若可行，下一步扩到 Hard 档的多零件图结构比对；若在真值上就辨识不稳（比如自遮挡太严重），那本身就说明 2D 视频评测机构正确性有信息论上的上限，这也是一个值得写出来的结论。</p>',45)])])}const g=t(n,[["render",r]]);export{c as __pageData,g as default};
